UPDATE DAILY_BATCH_EXECUTION
SET lease_until = #{newLeaseUntil}
WHERE daily_batch_execution_id = #{id}
  AND owner_id = #{ownerId}
  AND lease_token = #{leaseToken}
  AND status = 'RUNNING'
  AND lease_until >= #{now}

UPDATE DAILY_BATCH_EXECUTION
SET status        = #{status},
    completed_at  = #{completedAt},
    error_summary = #{errorSummary}
WHERE daily_batch_execution_id = #{id}
  AND owner_id = #{ownerId}
  AND lease_token = #{leaseToken}
  AND status = 'RUNNING'
  AND lease_until >= #{now}
